(function () {
    function showModal(element) {
        if (!element) return;
        element.classList.add("show");
        element.style.display = "block";
        element.removeAttribute("aria-hidden");
        element.setAttribute("aria-modal", "true");
        element.dispatchEvent(new Event("show.bs.modal"));
    }

    function hideModal(element) {
        if (!element) return;
        element.classList.remove("show");
        element.style.display = "none";
        element.setAttribute("aria-hidden", "true");
        element.removeAttribute("aria-modal");
    }

    class Modal {
        constructor(element) {
            this.element = element;
            if (element) {
                element.__offlineModal = this;
            }
        }

        show() {
            showModal(this.element);
        }

        hide() {
            hideModal(this.element);
        }

        static getInstance(element) {
            return element ? element.__offlineModal || new Modal(element) : null;
        }
    }

    window.bootstrap = window.bootstrap || {};
    window.bootstrap.Modal = Modal;

    document.addEventListener("click", function (event) {
        const toggle = event.target.closest("[data-bs-toggle='modal']");
        if (toggle) {
            const selector = toggle.getAttribute("data-bs-target");
            showModal(document.querySelector(selector));
        }

        const dismiss = event.target.closest("[data-bs-dismiss='modal']");
        if (dismiss) {
            hideModal(dismiss.closest(".modal"));
        }
    });
}());
